struct SplitMix {
    size_t operator()(unsigned long long x) const {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }
};
using Freq = unordered_map<long long, long long, SplitMix>;

int main() {
    readAll();
    int n = num(), m = num(), q = num();
    vector<long long> a(n);
    Freq ca, cb;
    ca.reserve(1 << 20), cb.reserve(1 << 19);
    for (auto& x : a) ca[x = num()]++;
    for (int j = 0; j < m; j++) cb[num()]++;
    string out;
    bool first = true;
    while (q--) {
        if (num() == 0) {
            int i = num();
            long long x = num();
            auto it = ca.find(a[i]);
            if (--it->second == 0) ca.erase(it);
            a[i] += x;
            ca[a[i]]++;
        } else {
            long long x = num(), total = 0;
            // Walk the side with fewer distinct values and look up the complement on the other side.
            const Freq& small = ca.size() <= cb.size() ? ca : cb;
            const Freq& big = ca.size() <= cb.size() ? cb : ca;
            for (const auto& [v, c] : small) {
                auto it = big.find(x - v);
                if (it != big.end()) total += c * it->second;
            }
            if (!first) out += ' ';
            first = false;
            out += to_string(total);
        }
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    /** Value -> frequency, with the live keys kept in dense arrays so a query walks only distinct values. */
    static final class Freq {
        static final int CAP = 1 << 20, MASK = CAP - 1;
        final long[] tableKey = new long[CAP];
        final int[] tableIdx = new int[CAP];  // dense index + 1; 0 = empty, -1 = deleted
        final long[] keys, cnt;
        int size = 0;

        Freq(int maxKeys) {
            keys = new long[maxKeys];
            cnt = new long[maxKeys];
        }

        int slot(long k) {
            int h = (int) ((k * 0x9E3779B97F4A7C15L) >>> 44) & MASK;
            while (tableIdx[h] != 0 && (tableIdx[h] < 0 || tableKey[h] != k)) h = (h + 1) & MASK;
            return h;
        }

        long get(long k) {
            int h = slot(k);
            return tableIdx[h] > 0 ? cnt[tableIdx[h] - 1] : 0;
        }

        void add(long k, long d) {
            int h = slot(k);
            if (tableIdx[h] == 0) {
                tableKey[h] = k;
                keys[size] = k;
                cnt[size] = 0;
                tableIdx[h] = ++size;
            }
            int i = tableIdx[h] - 1;
            cnt[i] += d;
            if (cnt[i] == 0) {
                int last = size - 1;
                if (i != last) {
                    keys[i] = keys[last];
                    cnt[i] = cnt[last];
                    tableIdx[slot(keys[i])] = i + 1;
                }
                size--;
                tableIdx[h] = -1;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        int n = (int) num(), m = (int) num(), q = (int) num();
        long[] a = new long[n];
        Freq ca = new Freq(n + q + 1), cb = new Freq(m + 1);
        for (int i = 0; i < n; i++) ca.add(a[i] = num(), 1);
        for (int j = 0; j < m; j++) cb.add(num(), 1);
        StringBuilder out = new StringBuilder();
        boolean first = true;
        while (q-- > 0) {
            if (num() == 0) {
                int i = (int) num();
                long x = num();
                ca.add(a[i], -1);
                a[i] += x;
                ca.add(a[i], 1);
            } else {
                long x = num(), total = 0;
                // Walk the side with fewer distinct values and look up the complement on the other side.
                Freq small = ca.size <= cb.size ? ca : cb, big = small == ca ? cb : ca;
                for (int k = 0; k < small.size; k++) total += small.cnt[k] * big.get(x - small.keys[k]);
                if (!first) out.append(' ');
                first = false;
                out.append(total);
            }
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

// freq maps value -> frequency; live keys sit in dense slices so a query walks only distinct values.
type freq struct {
	idx  map[int64]int
	keys []int64
	cnt  []int64
}

func newFreq(hint int) *freq {
	return &freq{idx: make(map[int64]int, hint)}
}

func (f *freq) get(k int64) int64 {
	if i, ok := f.idx[k]; ok {
		return f.cnt[i]
	}
	return 0
}

func (f *freq) add(k, d int64) {
	i, ok := f.idx[k]
	if !ok {
		i = len(f.keys)
		f.idx[k] = i
		f.keys = append(f.keys, k)
		f.cnt = append(f.cnt, 0)
	}
	f.cnt[i] += d
	if f.cnt[i] == 0 {
		last := len(f.keys) - 1
		if i != last {
			f.keys[i], f.cnt[i] = f.keys[last], f.cnt[last]
			f.idx[f.keys[i]] = i
		}
		f.keys, f.cnt = f.keys[:last], f.cnt[:last]
		delete(f.idx, k)
	}
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, q := int(num()), int(num()), int(num())
	a := make([]int64, n)
	ca, cb := newFreq(n), newFreq(m)
	for i := range a {
		a[i] = num()
		ca.add(a[i], 1)
	}
	for j := 0; j < m; j++ {
		cb.add(num(), 1)
	}
	out := []byte{}
	first := true
	for ; q > 0; q-- {
		if num() == 0 {
			i, x := num(), num()
			ca.add(a[i], -1)
			a[i] += x
			ca.add(a[i], 1)
		} else {
			x := num()
			var total int64
			// Walk the side with fewer distinct values and look up the complement on the other side.
			small, big := ca, cb
			if len(ca.keys) > len(cb.keys) {
				small, big = cb, ca
			}
			for k, v := range small.keys {
				if c, ok := big.idx[x-v]; ok {
					total += small.cnt[k] * big.cnt[c]
				}
			}
			if !first {
				out = append(out, ' ')
			}
			first = false
			out = strconv.AppendInt(out, total, 10)
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
